CREATE TABLE chamados (
    id VARCHAR(10) PRIMARY KEY,
    protocol VARCHAR(30),
    type INT NOT NULL,
    subject VARCHAR(350),
    category VARCHAR(128),
    urgency VARCHAR(128),
    status VARCHAR(128) NOT NULL DEFAULT 'Novo',
    baseStatus VARCHAR(128),
    justification VARCHAR(128),
    origin INT,
    createdDate TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    originEmailAccount VARCHAR(128),
    owner VARCHAR(128),
    ownerTeam VARCHAR(128),
    createdBy VARCHAR(128) NOT NULL,
    serviceFirstLevel VARCHAR(1024),
    serviceSecondLevel VARCHAR(1024),
    tags TEXT,
    resolvedIn TIMESTAMP WITH TIME ZONE NULL,
    reopenedIn TIMESTAMP WITH TIME ZONE NULL,
    closedIn TIMESTAMP WITH TIME ZONE NULL,
    lastActionDate TIMESTAMP WITH TIME ZONE,
    actionCount INT,
    lastUpdate TIMESTAMP WITH TIME ZONE,
    lifetimeWorkingTime INT,
    stoppedTime INT,
    stoppedTimeWorkingTime INT,
    resolvedInFirstCall BOOLEAN,
    slaAgreement VARCHAR(128),
    slaAgreementRule VARCHAR(128),
    slaSolutionTime INT,
    slaResponseTime INT,
    slaSolutionDate TIMESTAMP WITH TIME ZONE,
    sla_met VARCHAR(20),
    is_reopened_7d VARCHAR(10)
);


